const POND = { x: -16.5, z: 5.0, R: 4.0, sx: 1.2, waterY: -0.07, depth: 1.8, // 1.8 m in the middle: deep enough to swim (per user)
  fishA: -0.52 };                                  // bank angle of the fishing spot (east bank). Per user: at −0.12 the string-light
                                                    // anchor tree's canopy hung 0.1 m off the stool and filled the view when the catch was lifted; here every fixed
