{ // soft gravel edge (per user: gravel and grass looked like two separate textures): a feather ring in the same gravel
  // texture and UVs, from 0.6 m inside the patch edge (opaque, seamless with the patch) out to ~1 m beyond it (clear),
  // along a wavy line, tinted a little green as it thins so it blends into the grass
  const N = 220, edge = areaShape().getSpacedPoints(N).slice(0, N);
  const cx = (AREA.x0 + AREA.x1) / 2, cy = -(AREA.z0 + AREA.z1) / 2;
  const rows = [[-0.6, 1, [1, 1, 1]], [0.15, 0.6, [0.9, 1.0, 0.85]], [0.55, 0.22, [0.82, 0.98, 0.76]], [1.0, 0, [0.8, 0.95, 0.75]]];   // [offset, alpha, tint]
  const pos = [], uv = [], col = [], idx = [];
  for (let i = 0; i < N; i++) {
    const a = edge[(i + N - 1) % N], b = edge[(i + 1) % N], p = edge[i];
    let nx = b.y - a.y, ny = -(b.x - a.x); const l = Math.hypot(nx, ny) || 1; nx /= l; ny /= l;
    if (nx * (p.x - cx) + ny * (p.y - cy) < 0) { nx = -nx; ny = -ny; }                 // point outward
    const wob = 0.35 * Math.sin(i * 0.37) + 0.2 * Math.sin(i * 1.13 + 1) + 0.12 * Math.sin(i * 2.9 + 2);
    for (const [off, al, t] of rows) { const o = off > 0 ? off + wob * off : off, x = p.x + nx * o, y = p.y + ny * o;
      pos.push(x, y, 0); uv.push(x, y); col.push(t[0], t[1], t[2], al); }
  }
  const R = rows.length;
  for (let i = 0; i < N; i++) { const j = (i + 1) % N; for (let r = 0; r < R - 1; r++) { const a = i * R + r, b = j * R + r; idx.push(a, b, a + 1, a + 1, b, b + 1); } }
  const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3)); g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 4)); g.setIndex(idx); g.computeVertexNormals();
  if (g.attributes.normal.getZ(0) < 0) { g.index.array.reverse(); g.computeVertexNormals(); }
  const fe = new THREE.Mesh(g, new THREE.MeshStandardMaterial({ map: siteTex, roughness: 1, vertexColors: true, transparent: true, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -1, polygonOffsetUnits: -1 }));
  fe.rotation.x = -Math.PI / 2; fe.position.y = 0.0055; fe.receiveShadow = true; fe.renderOrder = 1; scene.add(fe);
}

await stage('Building the tent models…', 35);
// ---------- flysheet materials ----------
const matFly    = new THREE.MeshStandardMaterial({ color: 0xc3b091, roughness: 0.85, side: THREE.DoubleSide }); // clean khaki tarp (no texture)
const matPole   = new THREE.MeshStandardMaterial({ color: 0x333940, roughness: 0.6, metalness: 0.4 });

// ---------- tent models ----------
// makeBlock10(opts), makeBlock05(), makeSofa() — copied verbatim from block10_mock.html / block05.html /
// sofa_mock.html by build_combos.py into isolated closures. Re-run `python3 build_combos.py` after editing a model.
// the tent model builders (makeBlock10 / 09 / 05, makeSofa, makeJointCloth, makeDockCloth) are GENERATED into
// tents.js by build_combos.py from the single-model pages — edit those pages, then re-run the script

let flyGroup = null;
const lineMat = new THREE.LineBasicMaterial({ color: 0x2f3a2a }); // shared (was re-created — and leaked — on every slider move)
function buildFlysheet() {
  if (flyGroup) { scene.remove(flyGroup); flyGroup.traverse(o => o.geometry?.dispose()); } // materials are shared (hoisted)
  const fg = new THREE.Group();

  // real tarp: fixed 7 × 6 m, ridge at 3.0 m, edges at eaveH
  const slope = (FLY_RIDGE_H - eaveH) / FLY_W_HALF;
  const xE = FLY_W_HALF;             // tarp edge (fixed)
  const hE = eaveH;
  const z0 = -FLY_L_HALF, z1 = FLY_L_HALF;   // NOTE: three.js Y=up, Z=depth

  const geo = new THREE.BufferGeometry();
  const v = [
    // left slope quad: centerline (0,H,z) down to left edge (-xE,hE,z)
    -xE, hE, z0,   0, FLY_RIDGE_H, z0,   0, FLY_RIDGE_H, z1,
    -xE, hE, z0,   0, FLY_RIDGE_H, z1,  -xE, hE, z1,
    // right slope quad: centerline down to right edge (xE,hE,z)
     xE, hE, z0,   xE, hE, z1,          0, FLY_RIDGE_H, z1,
     xE, hE, z0,   0, FLY_RIDGE_H, z1,  0, FLY_RIDGE_H, z0,
  ];
  geo.setAttribute('position', new THREE.Float32BufferAttribute(v, 3));
  // UVs in metres so the tarp texture tiles at real scale
  {
    const uv = new Float32Array((v.length / 3) * 2);
    for (let i = 0; i < v.length / 3; i++) {
      uv[i * 2]     = v[i * 3] + xE;   // 0..7 m across
      uv[i * 2 + 1] = v[i * 3 + 2] - z0; // 0..6 m along
    }
    geo.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  }
  geo.computeVertexNormals();
  const tarp = new THREE.Mesh(geo, matFly);
  tarp.castShadow = tarp.receiveShadow = true;
  fg.add(tarp);

  // thin support poles (35 mm dia): two at the ridge ends + one at each tarp corner
  const poleR = 0.0175; // 35 mm diameter
  for (const py of [-FLY_L_HALF, FLY_L_HALF]) {
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(poleR, poleR, FLY_RIDGE_H, 10), matPole);
    pole.position.set(0, FLY_RIDGE_H / 2, py);
    pole.castShadow = true;
    fg.add(pole);
  }
  for (const px of [-xE, xE]) {
    for (const py of [z0, z1]) {
      const cpole = new THREE.Mesh(new THREE.CylinderGeometry(poleR, poleR, hE, 10), matPole);
      cpole.position.set(px, hE / 2, py);
      cpole.castShadow = true;
      fg.add(cpole);
    }
  }

  // guy lines + stakes at the four eave corners
  // real peg: tapered steel pin + pointed tip + T-head, tilted ~35° away from its anchor
  // so the guy-line pull drives it in rather than levering it out. Returns the T-head position.
  const addPeg = (px, pz, ax, az) => {
    const peg = new THREE.Group();
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.008, 0.30, 6), matPole);
    shaft.position.y = 0.15;
    const tip = new THREE.Mesh(new THREE.ConeGeometry(0.009, 0.07, 6), matPole);
    tip.rotation.x = Math.PI; // point down
    tip.position.y = -0.02;
    const headBar = new THREE.Mesh(new THREE.CylinderGeometry(0.013, 0.013, 0.10, 8), matPole);
    headBar.rotation.z = Math.PI / 2; // horizontal T-bar
    headBar.position.y = 0.30;
    peg.add(shaft, tip, headBar);
    peg.traverse(o => { if (o.isMesh) o.castShadow = true; });
    peg.position.set(px, 0, pz);
    const toAnchor = new THREE.Vector3(ax - px, 0, az - pz).normalize();
    const tiltAxis = new THREE.Vector3().crossVectors(toAnchor, new THREE.Vector3(0, 1, 0));
    peg.quaternion.setFromAxisAngle(tiltAxis.normalize(), 0.6); // top leans away from the pull
    fg.add(peg);
    return new THREE.Vector3(0, 0.30, 0).applyQuaternion(peg.quaternion).add(peg.position);
  };

  for (const sx of [-1, 1]) {
    for (const [sy, ySign] of [[z0, -1], [z1, 1]]) {
      const stakeX = sx * (xE + 1.1);
      const stakeY = sy + ySign * 0.9;
      // guy line runs from the eave corner to the peg's T-head
      const headPos = addPeg(stakeX, stakeY, sx * xE, sy);
      const lg = new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(sx * xE, hE, sy),
        headPos
      ]);
      fg.add(new THREE.Line(lg, lineMat));
    }
  }

  // centre ridge-end poles: two support paracords each, splayed OUTWARDS along ±z (V-brace) —
  // tied at the very top of the pole so it can't tip in any direction
  for (const py of [-FLY_L_HALF, FLY_L_HALF]) {
    const out = Math.sign(py); // outward = away from tarp centre along z
    for (const sx of [-1, 1]) {
      const pegX = sx * 1.6;
      const pegZ = py + out * 1.8;
      const headPos = addPeg(pegX, pegZ, 0, py); // anchor = the centre pole
      const lg = new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(0, FLY_RIDGE_H, py), // tied at the top of the pole
        headPos
      ]);
      fg.add(new THREE.Line(lg, lineMat));
    }
  }

  scene.add(fg);
  flyGroup = fg; fg.userData.dynamic = true;   // rebuilt by the gap slider
}

