// ---------- woven outdoor rugs (added in front of the Block 10 entrances once the tents exist) ----------
function makeRug(w, d, [base, band, accent]) {
  const c = document.createElement('canvas'); c.width = 512; c.height = Math.round(512 * d / w);
  const ctx = c.getContext('2d'), W = c.width, H = c.height;
  ctx.fillStyle = base; ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = band; ctx.lineWidth = 10; ctx.strokeRect(14, 14, W - 28, H - 28);    // border bands
  ctx.lineWidth = 4; ctx.strokeRect(32, 32, W - 64, H - 64);
  ctx.fillStyle = accent;                                                                // centre row of diamonds
  const n = 7, step = (W - 120) / n;
  for (let i = 0; i < n; i++) {
    const cx = 60 + step * (i + 0.5), cy = H / 2, r = Math.min(step * 0.42, H * 0.2);
    ctx.beginPath(); ctx.moveTo(cx, cy - r); ctx.lineTo(cx + r, cy); ctx.lineTo(cx, cy + r); ctx.lineTo(cx - r, cy); ctx.closePath(); ctx.fill();
  }
  ctx.fillStyle = band;                                                                  // zigzag rows
  for (const yy of [H * 0.24, H * 0.76]) for (let x = 50; x < W - 50; x += 16) {
    ctx.beginPath(); ctx.moveTo(x, yy + 5); ctx.lineTo(x + 8, yy - 5); ctx.lineTo(x + 16, yy + 5); ctx.lineTo(x + 8, yy + 1); ctx.closePath(); ctx.fill();
  }
  ctx.globalAlpha = 0.08; ctx.fillStyle = '#000';                                        // woven texture
  for (let y = 0; y < H; y += 3) ctx.fillRect(0, y, W, 1);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const rug = new THREE.Mesh(new THREE.BoxGeometry(w, 0.005, d),
    new THREE.MeshStandardMaterial({ map: tex, roughness: 0.95 }));
  rug.receiveShadow = true;
  return rug;
}
// rug in front of a Block 10's gable entrance (tent-local, entrance faces +z; clears the 4.5 cm snow skirt)
function addEntranceRug(tent, palette) {
  const rug = makeRug(1.8, 1.1, palette);
  rug.position.set(0, 0.0025, 1.40 + 0.08 + 0.55);
  tent.add(rug);
}

// ---------- fishing spot (per user): folding stool, rod on a forked rest and a bucket on the pond's east bank.
// In first person, walk up to the stool and press E to sit down and cast; wait for the bobber to dip, press E on the
// bite to reel a koi in (then it's released). WASD / Esc stands you up. Tapping the hint pill = E on touch screens. ----------
fishing = (() => {
  const P = POND, M = chairMats, V = (x, y, z) => new THREE.Vector3(x, y, z);
  const a0 = P.fishA, edgeR = pondR(a0);
  const edge = V(P.x + Math.cos(a0) * edgeR * P.sx, 0, P.z + Math.sin(a0) * edgeR);
  const out = V(Math.cos(a0) / P.sx, 0, Math.sin(a0)).normalize();      // outward from the water (ellipse normal)
  const seat = edge.clone().addScaledVector(out, 0.85);
  const g = new THREE.Group();                                         // local +z faces the water
  g.position.copy(seat); g.rotation.y = Math.atan2(-out.x, -out.z);
  scene.add(g);
  const toWorld = v => g.localToWorld(v.clone());
  g.updateMatrixWorld(true);

  // folding stool: two X-frames, top rails, khaki canvas sling (seat 42 cm)
  const SH = 0.42;
  for (const sx of [-0.17, 0.17]) {
    g.add(bentTube([V(sx, 0.01, -0.15), V(sx, SH - 0.02, 0.15)], 0.01, M.frame), bentTube([V(sx, 0.01, 0.15), V(sx, SH - 0.02, -0.15)], 0.01, M.frame));
    const pin = new THREE.Mesh(new THREE.CylinderGeometry(0.007, 0.007, 0.035, 8), M.black);
    pin.rotation.z = Math.PI / 2; pin.position.set(sx, (SH - 0.01) / 2, 0); g.add(pin);
  }
  for (const sz of [-0.15, 0.15]) g.add(bentTube([V(-0.19, SH - 0.02, sz), V(0.19, SH - 0.02, sz)], 0.01, M.frame));
  g.add(sling((u, v, o) => o.set(-0.17 + 0.34 * u, SH - 0.012 - 0.02 * Math.sin(Math.PI * u), 0.15 - 0.3 * v), 8, 6, M.canvas));
  // bucket beside the stool
  const bucket = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.11, 0.26, 18, 1, true),
    new THREE.MeshStandardMaterial({ color: 0x3b6e8f, roughness: 0.6, side: THREE.DoubleSide }));
  bucket.position.set(-0.42, 0.13, 0.05); g.add(bucket);
  const bucketBase = new THREE.Mesh(new THREE.CircleGeometry(0.11, 18), bucket.material);
  bucketBase.rotation.x = -Math.PI / 2; bucketBase.position.set(-0.42, 0.005, 0.05); g.add(bucketBase);
  const bail = new THREE.Mesh(new THREE.TorusGeometry(0.13, 0.003, 4, 20, Math.PI), M.black);
  bail.position.set(-0.42, 0.26, 0.05); bail.rotation.y = 0.3; g.add(bail);
  // forked rod rest pushed into the bank at the water's edge
  const restZ = 0.85 - 0.18, restTop = V(0.32, 0.56, restZ);
  g.add(bentTube([V(0.32, -0.05, restZ), restTop], 0.008, M.frame));
  for (const sx of [-1, 1]) g.add(bentTube([restTop, V(0.32 + sx * 0.035, 0.63, restZ)], 0.006, M.frame));

  // rod: 2.4 m carbon blank + cork grip + spinning reel + guides; its group's +z runs butt → tip
  const ROD_L = 2.4;
  const rod = new THREE.Group(); rod.userData.dynamic = true;     // re-posed every frame while fishing
  const blankGeo = new THREE.CylinderGeometry(0.003, 0.008, ROD_L - 0.3, 8); blankGeo.rotateX(Math.PI / 2); blankGeo.translate(0, 0, 0.3 + (ROD_L - 0.3) / 2);
  rod.add(new THREE.Mesh(blankGeo, new THREE.MeshStandardMaterial({ color: 0x1f2a24, roughness: 0.35, metalness: 0.3 })));
  const gripGeo = new THREE.CylinderGeometry(0.014, 0.013, 0.32, 12); gripGeo.rotateX(Math.PI / 2); gripGeo.translate(0, 0, 0.16);
  rod.add(new THREE.Mesh(gripGeo, new THREE.MeshStandardMaterial({ color: 0xb9925e, roughness: 0.9 })));
  const reelMat = new THREE.MeshStandardMaterial({ color: 0x2b2d31, roughness: 0.4, metalness: 0.6 });
  const spool = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 0.035, 16), reelMat);
  spool.rotation.x = Math.PI / 2; spool.position.set(0, -0.06, 0.36); rod.add(spool);
  rod.add(bentTube([V(0, -0.012, 0.34), V(0, -0.045, 0.36)], 0.004, reelMat));
  const crank = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.005, 0.008), reelMat); crank.position.set(0.03, -0.06, 0.36); rod.add(crank);
  for (const [z, r] of [[0.7, 0.012], [1.2, 0.009], [1.7, 0.007], [2.1, 0.005]]) {
    const guide = new THREE.Mesh(new THREE.TorusGeometry(r, 0.0015, 4, 12), reelMat);
    guide.position.set(0, -0.01 - r, z); rod.add(guide);
  }
  rod.traverse(o => { if (o.isMesh) o.castShadow = true; });
  g.add(rod);
  const tipWorld = () => rod.localToWorld(V(0, 0, ROD_L));
  // pose the rod: butt at `butt` (local to g), pointing at `aim` (local to g)
  const pose = (butt, aim) => { rod.position.copy(butt); rod.lookAt(toWorld(aim)); };
  const restPose = () => pose(V(0.32, 0.02, -0.35), restTop.clone().add(V(0, 0.012, 0)));
  restPose();

  // bobber (red top / white bottom) + line
  const bobber = new THREE.Group(); bobber.userData.dynamic = true;
  const red = new THREE.MeshStandardMaterial({ color: 0xd9381e, roughness: 0.4 }), white = new THREE.MeshStandardMaterial({ color: 0xf4f4f0, roughness: 0.4 });
  bobber.add(new THREE.Mesh(new THREE.SphereGeometry(0.022, 14, 8, 0, Math.PI * 2, 0, Math.PI / 2), red));
  bobber.add(new THREE.Mesh(new THREE.SphereGeometry(0.022, 14, 8, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), white));
  const stick = new THREE.Mesh(new THREE.CylinderGeometry(0.003, 0.003, 0.05, 6), red); stick.position.y = 0.04; bobber.add(stick);
  scene.add(bobber);
  const LINE_N = 24, linePos = new Float32Array(LINE_N * 3);
  const lineGeo = new THREE.BufferGeometry(); lineGeo.setAttribute('position', new THREE.BufferAttribute(linePos, 3));
  const line = new THREE.Line(lineGeo, new THREE.LineBasicMaterial({ color: 0xe8e8e8, transparent: true, opacity: 0.75 }));
  line.frustumCulled = false;
  scene.add(line);
  const drawLine = (a, b, sag) => {
    for (let i = 0; i < LINE_N; i++) {
      const t = i / (LINE_N - 1), y = a.y + (b.y - a.y) * t - sag * 4 * t * (1 - t);
      linePos.set([a.x + (b.x - a.x) * t, y, a.z + (b.z - a.z) * t], i * 3);
    }
    lineGeo.attributes.position.needsUpdate = true;
  };

  // HUD (the same pill as the walk hint, above it; tap = E)
  const hud = document.getElementById('fishHud');
  const say = (html, alert = false) => { hud.innerHTML = html; hud.style.display = 'block'; hud.classList.toggle('alert', alert); };
  const hush = () => { hud.style.display = 'none'; hud.classList.remove('alert'); };
  // touch screens (per user: no way to stop fishing on mobile): tap the pill = E, and a Stand up button shows while fishing
  const TOUCH = matchMedia('(pointer: coarse)').matches, exitBtn = document.getElementById('fishExit');
  const IDLE = TOUCH ? '<b>Tap</b> to cast' : '<kbd>E</kbd> cast · <kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> / <kbd>Esc</kbd> stand up';

  let active = false, state = 'ready', tState = 0, biteAt = 0, caught = 0, saved = null, catchFish = null, catchName = '', catchCm = 0;
  const target = V(0, 0, 0), from = V(0, 0, 0), look = V(0, 0, 0), eye = toWorld(V(0, 1.02, -0.08));
  const go = s => { state = s; tState = 0; };

  function start() {
    if (active) return;
    saved = { walking, pos: camera.position.clone(), quat: camera.quaternion.clone(), target: controls.target.clone() };
    if (fpControls.isLocked) fpControls.unlock();
    controls.enabled = false;
    walkHint.style.display = 'none'; osControls.style.display = 'none';
    releaseKeys();
    active = true; exitBtn.style.display = 'block';
    look.copy(toWorld(V(0, 0, 3)));
    cast();
  }
  function stop() {
    if (!active) return;
    active = false; hush(); exitBtn.style.display = 'none';
    if (catchFish) { scene.remove(catchFish.f); catchFish = null; }
    restPose();
    if (saved.walking) {                    // stand up beside the stool, still in first person, facing the water
      camera.position.copy(toWorld(V(0.15, 0, -0.55))); camera.position.y = EYE_H;
      walkHint.style.display = 'block'; updateOS();
    } else {                                // back to the orbit view you had
      camera.position.copy(saved.pos); camera.quaternion.copy(saved.quat); controls.target.copy(saved.target);
      controls.enabled = true; controls.update();
    }
  }
  function cast() {
    // a spot 3–4.5 m out over the water, a little to either side, that is actually in the pond
    for (let k = 0; k < 20; k++) {
      target.copy(toWorld(V((Math.random() - 0.5) * 1.6, 0, 0.85 + 3 + Math.random() * 1.5)));
      const w = pond.depthAt(target.x, target.z);
      if (w && w.waterY - w.bedY > 0.4) break;
    }
    target.y = P.waterY;
    go('cast');
    say('Casting…');
  }
  function onE() {
    if (!active) {
      // first person only (per user): walk up to the stool and press E
      if (!walking || car?.active || Math.hypot(camera.position.x - seat.x, camera.position.z - seat.z) > 2.5) return;
      start(); return;
    }
    if (state === 'ready') cast();
    else if (state === 'wait') { go('ready'); say('Too early — the fish swam off. ' + IDLE); }
    else if (state === 'bite') {
      catchFish = pond.makeKoi(); catchName = catchFish.name; catchCm = 28 + Math.round(Math.random() * 36);
      catchFish.f.scale.setScalar(catchCm / 56);
      scene.add(catchFish.f);
      go('reel'); say('Reeling in…');
    }
  }

  const _v = V(0, 0, 0);
  function update(dt) {
    const t = performance.now() * 0.001;
    if (!active) {
      // first-person prompt when you stand next to the stool
      const near = walking && !car?.active && Math.hypot(camera.position.x - seat.x, camera.position.z - seat.z) < 2.2;
      if (near) say(TOUCH ? '<b>Tap</b> to sit down and fish' : '<kbd>E</kbd> sit down and fish'); else if (hud.style.display !== 'none') hush();
      // idle: the bobber hangs a little below the rod tip on the rest
      const tip = tipWorld();
      bobber.position.set(tip.x, tip.y - 0.3, tip.z);
      drawLine(tip, bobber.position, 0);
      return;
    }
    tState += dt;
    const hands = V(0.1, 0.66, 0.2);
    if (state === 'cast') {
      // rod swings back (tip up and behind) then whips forward; the bobber flies a lob to the target
      const k = Math.min(tState / 1.1, 1);
      const pitch = k < 0.4 ? THREE.MathUtils.lerp(0.5, 1.45, k / 0.4) : THREE.MathUtils.lerp(1.45, 0.42, (k - 0.4) / 0.6);
      pose(hands, hands.clone().add(V(0.05, Math.sin(pitch) * 2, Math.cos(pitch) * 2)));
      const tip = tipWorld();
      if (k < 0.45) { bobber.position.set(tip.x, tip.y - 0.3, tip.z); from.copy(bobber.position); }
      else {
        const f = (k - 0.45) / 0.55;
        bobber.position.lerpVectors(from, target, f); bobber.position.y += Math.sin(Math.PI * f) * 1.2;
      }
      drawLine(tip, bobber.position, 0.05);
      if (k >= 1) { go('wait'); biteAt = 3 + Math.random() * 6; say('Waiting for a bite… ' + IDLE.replace('cast', 'strike')); }
    } else {
      // rod held low over the water; tip lifts while reeling
      const pitch = state === 'reel' || state === 'caught' ? 1.0 : 0.42;
      pose(hands, hands.clone().add(V(0.05, Math.sin(pitch) * 2, Math.cos(pitch) * 2)));
    }
    const tip = tipWorld();
    if (state === 'wait' || state === 'bite' || state === 'ready') {
      let dip = 0;
      if (state === 'wait') {
        const pre = biteAt - tState;                       // two nibbles in the last 1.4 s before the bite
        if (pre < 1.4 && pre > 0) dip = Math.max(0, Math.sin(pre * 9)) * 0.012;
        if (tState >= biteAt) { go('bite'); say(TOUCH ? 'Bite! <b>Tap</b>!' : 'Bite! Press <kbd>E</kbd>!', true); }
      }
      if (state === 'bite') {
        dip = 0.06;                                        // pulled under, tugging sideways
        if (tState > 1.3) { go('ready'); say('It got away… ' + IDLE); }
      }
      bobber.position.set(target.x + (state === 'bite' ? Math.sin(t * 13) * 0.02 : 0),
        P.waterY + 0.008 + Math.sin(t * 2.4) * 0.004 - dip, target.z);
      if (state === 'ready') { bobber.position.copy(tip); bobber.position.y -= 0.3; }
      drawLine(tip, bobber.position, state === 'ready' ? 0 : 0.12);
    }
    if (state === 'reel' && catchFish) {
      // the koi is dragged from the bobber to the bank below the rod tip, then lifted out, thrashing
      const k = Math.min(tState / 1.8, 1);
      const bank = toWorld(V(0.1, 0, 0.7)); bank.y = P.waterY - 0.05;
      if (k < 0.75) { _v.lerpVectors(target, bank, k / 0.75); _v.y = P.waterY - 0.08; }
      else { _v.copy(bank).lerp(V(tip.x, tip.y - 0.35, tip.z), (k - 0.75) / 0.25); }
      catchFish.f.position.copy(_v);
      catchFish.f.lookAt(k < 0.75 ? bank : V(_v.x, _v.y - 1, _v.z));
      catchFish.swim(t * 24);                       // thrashing
      bobber.position.copy(_v); bobber.position.y += 0.12;
      drawLine(tip, bobber.position, 0.02);
      if (k >= 1) {
        caught++;
        go('caught');
        say(`🎣 You caught a <b>${catchCm} cm ${catchName}</b> koi! &nbsp;(${caught} caught) — released back into the pond`);
      }
    }
    if (state === 'caught' && catchFish) {
      // dangling under the tip, wriggling; then let go
      catchFish.f.position.set(tip.x, tip.y - 0.35 - catchCm / 200, tip.z);
      catchFish.f.rotation.set(-Math.PI / 2 + Math.sin(t * 9) * 0.25, Math.sin(t * 5) * 0.4, 0);
      catchFish.swim(t * 18);
      bobber.position.set(tip.x, tip.y - 0.25, tip.z);
      drawLine(tip, bobber.position, 0);
      if (tState > 3.2) { scene.remove(catchFish.f); catchFish = null; go('ready'); say(IDLE); }
    }
    // seated view: eyes over the stool, looking at the bobber (or the catch), eased
    const want = state === 'caught' && catchFish ? catchFish.f.position : (state === 'cast' || state === 'ready' ? toWorld(V(0, 0, 3.5)) : bobber.position);
    look.lerp(want, Math.min(1, dt * 3));
    camera.position.lerp(eye, Math.min(1, dt * 4));
    camera.lookAt(look);
  }
  return { update, onE, start, stop, seat, get active() { return active; } };
})();

// ---------- string lights (catenary between poles + anchor trees) ----------
const bulbMat = new THREE.MeshStandardMaterial({ color: 0x3a3a30, emissive: 0xffc46b, emissiveIntensity: 0 });
function makeString(p1, p2, sag) {
  const mid = p1.clone().add(p2).multiplyScalar(0.5); mid.y -= sag;
  const pts = new THREE.QuadraticBezierCurve3(p1, mid, p2).getPoints(48);
  scene.add(new THREE.Mesh(
    new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 64, 0.008, 5),
    new THREE.MeshStandardMaterial({ color: 0x22221e })
  ));
  const bulbGeo = new THREE.SphereGeometry(0.035, 8, 6);
  let acc = 0;
  for (let i = 1; i < pts.length - 1; i++) {
    acc += pts[i].distanceTo(pts[i - 1]);
    if (acc >= 0.4) {
      acc = 0;
      const b = new THREE.Mesh(bulbGeo, bulbMat);
      b.position.copy(pts[i]); b.position.y -= 0.05;
      scene.add(b);
    }
  }
}
// per user: the flysheet pole → pole string and the tree → pole strings (the two wooden festoon posts by the fire and
// their strings were removed)
makeString(new THREE.Vector3(0, 2.95, 3), new THREE.Vector3(0, 2.95, -3), 0.7);     // pole → pole over the gap
makeString(new THREE.Vector3(0, 2.95, 3), new THREE.Vector3(-9.5, 4.0, 6.5), 0.8);   // front pole → tree A
makeString(new THREE.Vector3(0, 2.95, -3), new THREE.Vector3(9.5, 4.0, -6.5), 0.8);  // back pole → tree B
const stringLight = new THREE.PointLight(0xffc46b, 0, 10, 2);
stringLight.position.set(0, 2.3, 0);
scene.add(stringLight);
// warm glow where the string lights are tied into the two anchor trees (per user: at night those trees stayed dark)
// Each sits ~3 m out from its trunk along the string toward the flysheet pole — outside the canopy (inside it, it
// burned a hot spot into the foliage) — so the string's last bulbs wash over the tree.
const treeLights = [[[-9.5, 6.5], [0, 3]], [[9.5, -6.5], [0, -3]]].map(([[tx, tz], [px, pz]]) => {
  const d = new THREE.Vector2(px - tx, pz - tz).normalize();
  const l = new THREE.PointLight(0xffc46b, 0, 9, 1.4);
  l.position.set(tx + d.x * 3.0, 3.4, tz + d.y * 3.0);
  scene.add(l);
  return l;
});

// ---------- night mode ----------
let isNight = false;
// ---------- day ↔ night and rain fade in and out (per user: they used to switch instantly) ----------
// isNight / raining flip at once (the logic: animals, fireflies, campers…), while two blend factors ease toward them —
// nightK over ~5 s, rainK over ~4 s — and everything you SEE and HEAR follows those: sun and sky light, fog colour and
// range, a night sky dome fading in over the day one, stars, sun disc, clouds, the overcast tint, firelight, the
// lanterns / string / table lights, rain streaks and the bird / cricket / rain mix. The pond's night reflections can
// only swap, so they swap half-way.
let nightK = 0, rainK = 0, pondNight = false;
const skyNightMat = new THREE.MeshBasicMaterial({ map: skyNightTex, side: THREE.BackSide, fog: false, transparent: true, opacity: 0, depthWrite: false });
const skyNight = new THREE.Mesh(new THREE.SphereGeometry(169, 32, 16), skyNightMat); skyNight.renderOrder = -1; skyGroup.add(skyNight);
const _fogC = new THREE.Color(), _fc2 = new THREE.Color(), _sunC = new THREE.Color();
const FOG = { day: new THREE.Color(0xcfe6f7), night: new THREE.Color(0x1a2440), dayRain: new THREE.Color(0x9ea8b2), nightRain: new THREE.Color(0x151b24) };
const SKYTINT = { day: new THREE.Color(0x9aa2ab), night: new THREE.Color(0x6b7280) }, WHITE = new THREE.Color(0xffffff);
const SUNC = { day: new THREE.Color(0xfff2d9), night: new THREE.Color(0x9db4ff) };
const lerp = THREE.MathUtils.lerp;
function fogBase() {
  _fogC.copy(FOG.day).lerp(FOG.night, nightK); _fc2.copy(FOG.dayRain).lerp(FOG.nightRain, nightK); _fogC.lerp(_fc2, rainK);
  return { c: _fogC, n: lerp(30, 14, rainK), f: lerp(90, 60, rainK) };
}
function applyLook() {                                 // everything visual, from nightK / rainK
  const n = nightK, r = rainK;
  sun.intensity = lerp(1.6, 0.35, n) * lerp(1, 0.3, r);
  sun.color.copy(_sunC.copy(SUNC.day).lerp(SUNC.night, n));
  // the night 'sun' is soft moonlight with no disc in the sky: the Cybertruck's steel goes satin at night, so it no
  // longer shows a sharp white sun highlight (per user)
  if (life?.truck?.steel) life.truck.steel.roughness = lerp(0.34, 0.85, n);
  hemi.intensity = lerp(0.85, 0.25, n) * lerp(1, 0.9, r);
  if (!wasUnder) { const fb = fogBase(); scene.fog.color.copy(fb.c); scene.fog.near = fb.n; scene.fog.far = fb.f; }
  skyNightMat.opacity = n;
  _fc2.copy(SKYTINT.day).lerp(SKYTINT.night, n); skyMat.color.copy(WHITE).lerp(_fc2, r); skyNightMat.color.copy(skyMat.color);
  stars.visible = n > 0.01; stars.material.opacity = 0.9 * n * (1 - 0.7 * r);
  for (const c of stars.children) c.material.opacity = 0.95 * n * (1 - 0.7 * r);
  const sunVis = (1 - n) * (1 - r); sunSprite.visible = sunVis > 0.01; sunSprite.material.opacity = sunVis;
  setCloudOpacity(lerp(lerp(0.85, 0.15, n), 1, r));
  if ((n > 0.5) !== pondNight) { pondNight = n > 0.5; pond.setNight(pondNight); }
  applyLights();
  life?.setMix(n, r);
}
function blendLook(dt) {                               // called every frame; does nothing once settled
  const tn = isNight ? 1 : 0, tr = raining ? 1 : 0;
  if (nightK === tn && rainK === tr) return;
  nightK = tn > nightK ? Math.min(tn, nightK + dt / 5) : Math.max(tn, nightK - dt / 5);
  rainK = tr > rainK ? Math.min(tr, rainK + dt / 4) : Math.max(tr, rainK - dt / 4);
  applyLook();
}
function setNight(on) {
  isNight = on;
  wasUnder = null;                            // re-apply the underwater fog next frame if diving
  life?.setNight(on);
}
// RAIN (key 5, per user): overcast — sun ×0.3, grey sky + heavier haze — on top of day or night (eased by rainK)
function applyWeather() {
  wasUnder = null;
  life?.setWeather(raining);
}
// all the camp's artificial lights — tent lanterns, table lanterns, string/festoon bulbs — follow the Lights switch
// (key 3, per user) and night mode; the campfire stays lit
let lightsOn = true;
function applyLights() {
  const nk = lightsOn ? nightK : 0;                              // night-only lights fade with the dusk / dawn
  bulbMat.emissiveIntensity = 2.4 * nk;                          // string bulbs glow
  stringLight.intensity = 1.6 * nk;
  for (const l of treeLights) l.intensity = 2.6 * nk;          // the anchor trees the strings are tied to
  for (const l of tableLamps) { l.glow.emissiveIntensity = 1.8 * nk; l.light.intensity = 0.9 * nk; }
  // tent lanterns: on by day (they light the interiors), brighter at night; the mesh screens glow warm from inside
  for (const t of [tentL, tentR, block05, u3b10, u3b09, u3b05, solo05]) {
    const L = t.userData.lantern, G = t.userData.lanternGlow;
    if (L.userData.base === undefined) { L.userData.base = L.intensity; G.userData.base = G.emissiveIntensity; }
    L.intensity = lightsOn ? L.userData.base * (1 + 2 * nightK) : 0;
    G.emissiveIntensity = lightsOn ? G.userData.base : 0;
    t.userData.matGableMesh.emissive.set(0xffb46a);
    t.userData.matGableMesh.emissiveIntensity = 0.3 * nk;
  }
  // (per user: performance) a light at zero brightness still costs every pixel in three.js — hide dark ones, so by
  // day the string/tree/table lights drop out of the shaders entirely (switching day ↔ night recompiles once)
  for (const l of [stringLight, ...treeLights, ...tableLamps.map(t => t.light), ...[tentL, tentR, block05, u3b10, u3b09, u3b05, solo05].map(t => t.userData.lantern)])
    l.visible = l.intensity > 0;
}

await stage('Pitching the tents…', 85);
// ---------- assemble ----------
// everything sits on the gravel (y 0.005): the tent floors are 2 mm above their own origin, so lift them by 6 mm or
// the gravel patch z-fights through the PVC floor
const TENT_Y = 0.006;
// left: Block 10 with its air bed (block10_mock.html). right: Block 10 + Block 05 exactly as in block10_05.html —
// Block 05 15 cm off the opened side, joined by the velcroed connection cloth (rebuilt in layoutTents, as the gap
// slider moves the tents); sofa in the Block 10 (backed against the closed back gable), air bed in the Block 05.
const tentL = makeBlock10({ bed: true });
const tentR = makeBlock10({ docked: true, dockOpen: true, bed: false });
const block05 = makeBlock05({ docked: true });
block05.rotation.y = Math.PI;     // door wall faces −x, against the right tent's +x side wall
