      const a = Math.random() * Math.PI * 2, r = 17 + Math.random() * 9, x = Math.cos(a) * r, z = Math.sin(a) * r;
      if (x > -12 && x < 13 && z > -9 && z < 16.5) continue;                       // not into the camp
      const d = Math.hypot(x - g.position.x, z - g.position.z); if (d < 8 || d > 26) continue;
