// ---------- adaptive resolution (perf) ----------
// Every ~2 s, judge the average frame time. Under ~40 fps → render at a lower pixel ratio (−15 %, floor 0.75 px/px
// and half the base); a steady 57+ fps for ~6 s → step back up. A step down that doesn't speed things up (e.g. a browser
// capped at 30 fps in power-saving mode) is undone and adapting stops, so quality is never lost for nothing.
const dpr = { scale: 1, t0: 0, n: 0, good: 0, prevAvg: 0, wentDown: false, locked: false, from: 0 };
window.__perf.dpr = dpr;                                                    // debug: current scale / locked
const pixelRatio = () => Math.max(Math.min(0.75, devicePixelRatio), Math.min(devicePixelRatio, MAX_DPR) * dpr.scale);
function adaptResolution() {                          // wall-clock frame time (the loop's dt is capped at 50 ms)
  const now = performance.now();
  if (dpr.locked || document.hidden || !dpr.from || now < dpr.from) { dpr.t0 = 0; return; }
  if (!dpr.t0) { dpr.t0 = now; dpr.n = 0; return; }
  dpr.n++;
  if (now - dpr.t0 < 2000) return;
  const avg = (now - dpr.t0) / 1000 / dpr.n, before = dpr.scale; dpr.t0 = now; dpr.n = 0;
  if (dpr.wentDown && avg > dpr.prevAvg * 0.93) { dpr.scale = dpr.prevScale; dpr.locked = true; }      // no gain: undo, stop
  else if (avg > 1 / 40 && dpr.scale > 0.5) dpr.scale = Math.max(0.5, dpr.scale - 0.15);
  else if (avg < 1 / 57 && dpr.scale < 1 && ++dpr.good >= 3) { dpr.scale = Math.min(1, dpr.scale + 0.1); dpr.good = 0; }
  if (avg >= 1 / 57) dpr.good = 0;
  dpr.wentDown = dpr.scale < before; dpr.prevAvg = avg; dpr.prevScale = before;
  if (dpr.scale !== before) renderer.setPixelRatio(pixelRatio());
}

// ---------- resize + loop ----------
// per user: on a phone rotation, 'resize' can fire before the new viewport size has settled, so fit() reads the
// container's real size and re-runs a few times after an orientation change
function fit() {
  const w = container.clientWidth || innerWidth, h = container.clientHeight || innerHeight;
  if (w < 2 || h < 2) return;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setPixelRatio(pixelRatio()); // window moved between monitors
  renderer.setSize(w, h, false);
  labelRenderer.setSize(w, h);
  if (scrollX || scrollY) scrollTo(0, 0);
}
addEventListener('resize', fit);
const fitSoon = () => { fit(); for (const ms of [120, 350, 700, 1200]) setTimeout(fit, ms); };
addEventListener('orientationchange', fitSoon);
screen.orientation?.addEventListener?.('change', fitSoon);
visualViewport?.addEventListener('resize', fit);

applyLights();                               // start-up: drop the lights that are dark by day from the shaders
await stage('Optimising…', 92);
// ---------- PERFORMANCE (per user): merge static meshes ----------
// Each static group (tents, the Block 10+09+05 unit, sofa, tables, chairs, gear, fire pit, pond props, hammock,
// SUV, …) is baked into ONE mesh per material (+ shadow flags / render order / depth material / attribute layout),
// in the group's own space — so groups the gap slider moves still move, and every material object is kept (night
// mode, lantern glows, gable-mesh glow keep working). Anything animated is tagged userData.dynamic and left alone,
// as are lights, sprites, points, lines, instanced meshes and meshes that carry children.
function mergeStatic(root) {
  root.updateMatrixWorld(true);
  const inv = new THREE.Matrix4().copy(root.matrixWorld).invert(), m = new THREE.Matrix4();
  const buckets = new Map();
  root.traverse(o => {
    if (!o.isMesh || o.isInstancedMesh || o.isSkinnedMesh || o === root || o.children.length || Array.isArray(o.material)) return;
    for (let p = o; p && p !== root; p = p.parent) if (p.userData.dynamic) return;
    const g = o.geometry, a = g.attributes;
    if (g.morphAttributes && Object.keys(g.morphAttributes).length) return;
    const sig = Object.keys(a).sort().map(k => k + a[k].itemSize).join(',') + (g.index ? '|i' : '|n');
    const key = [o.material.uuid, sig, o.castShadow, o.receiveShadow, o.renderOrder, o.customDepthMaterial?.uuid, o.visible, o.frustumCulled].join('|');
    let b = buckets.get(key);
    if (!b) buckets.set(key, b = { src: o, list: [] });
    b.list.push(o);
  });
  let removed = 0, added = 0;
  for (const { src, list } of buckets.values()) {
    if (list.length < 2) continue;
    const geos = list.map(o => {
      const geo = o.geometry.clone().applyMatrix4(m.multiplyMatrices(inv, o.matrixWorld));
      if (m.determinant() < 0) {                                       // mirrored part: flip the winding back
        if (geo.index) { const ix = geo.index.array; for (let i = 0; i < ix.length; i += 3) { const t = ix[i + 1]; ix[i + 1] = ix[i + 2]; ix[i + 2] = t; } }
        else for (const at of Object.values(geo.attributes)) { const arr = at.array, n = at.itemSize; for (let i = 0; i < at.count; i += 3) for (let k = 0; k < n; k++) { const t = arr[(i + 1) * n + k]; arr[(i + 1) * n + k] = arr[(i + 2) * n + k]; arr[(i + 2) * n + k] = t; } }
      }
      for (const k of Object.keys(geo.morphAttributes || {})) delete geo.morphAttributes[k];
      geo.clearGroups();
      return geo;
    });
    const merged = mergeGeometries(geos, false);
    if (!merged) continue;                                              // incompatible layout → leave as they were
    const mesh = new THREE.Mesh(merged, src.material);
    Object.assign(mesh, { castShadow: src.castShadow, receiveShadow: src.receiveShadow, renderOrder: src.renderOrder, frustumCulled: src.frustumCulled });
    if (src.customDepthMaterial) mesh.customDepthMaterial = src.customDepthMaterial;
    root.add(mesh); added++;
    for (const o of list) { o.removeFromParent(); removed++; }
  }
  return removed - added;
}
{
  let saved = 0;
  for (const g of [...scene.children]) if ((g.isGroup || g.type === 'Object3D') && !g.userData.dynamic) saved += mergeStatic(g);
  console.info(`[perf] merged static meshes: ${saved} fewer draw objects`);
}

await stage('Compiling shaders…', 95);
renderer.compile(scene, camera); // warm up every material now so the first frames don't stutter
// per user ("change to night or rain, everything freezes for a few seconds"): hidden lights drop out of the shaders
// (applyLights), so every change in the light COUNT recompiled ~40 programs in one frame — the first switch to night
// took 5.5 s. Each material keeps a program per light setup, so compile the other setups now, behind the loader:
// night (string / tree / table lights), everything off (the Lights switch), and car headlights by day and by night.
{ const nightL = [stringLight, ...treeLights, ...tableLamps.map(t => t.light)];
  const lanterns = [tentL, tentR, block05, u3b10, u3b09, u3b05, solo05].map(t => t.userData.lantern);
  const beams = (life?.car?.beams || []).slice(0, 2), all = [...nightL, ...lanterns, ...(life?.car?.beams || []), ...(life?.truck?.beams || [])];
  const saved = all.map(l => l.visible), jobs = [];
  for (const on of [[...nightL, ...lanterns], [], [...lanterns, ...beams], [...nightL, ...lanterns, ...beams]]) {
    for (const l of all) l.visible = false; for (const l of on) l.visible = true;
    jobs.push(renderer.compileAsync(scene, camera));               // issues the compiles now (parallel where the GPU allows)
  }
  all.forEach((l, i) => { l.visible = saved[i]; });
  await Promise.all(jobs);
  // compiles finish lazily on a program's first use (its link status check blocks) — touch them all now, behind the
  // loader, or the first switch still stalled for seconds with every program already cached
  for (const pr of renderer.info.programs) { pr.getUniforms(); pr.getAttributes(); }
}

const clock = new THREE.Clock();
let firstFrame = true;
let inPond = false, pondSpeed = 1, wasUnder = false, swimMove = 0; // swimming state (walk mode); swimMove 0…1 drives the swish sound
const _fwd = new THREE.Vector3(), _right = new THREE.Vector3(), _move = new THREE.Vector3(); // orbit-view WASD temps
renderer.setAnimationLoop(() => {
  const dt = Math.min(clock.getDelta(), 0.05);
  if (!dpr.from) dpr.from = performance.now() + 4000;   // let shaders / textures settle before judging speed
  adaptResolution();
  swimMove = 0;                               // set below only while walking AND moving in the pond
  fishing?.update(dt);                        // fishing spot: prompt, cast/bite/reel, seated camera
  hammock?.update();                          // hammock: prompt, or ride the rocking sling while lying in it
  car?.update(dt);                            // the G-Class: prompt, door, driving, chase camera
  acts?.update(clock.elapsedTime, dt);        // activities: marshmallows, logs, stones, stargazing, the car's back
  // WASD walk mode (keyboard, mouse look, or on-screen controls)
  if (fishing?.active) {
    // sitting on the fishing stool: the fishing spot drives the camera
  } else if (car?.active) {
    // driving: the car module moves the car and places the camera (car.update below)
  } else if (acts?.active) {
    // roasting / stargazing / sitting in the car's back: feet stay put (acts.update places the camera); look stays free
  } else if (hammock?.active) {
    // lying in the hammock: position rides the sling (hammock.update); mouse lock / drag-to-look still turn the view
  } else if (walking) {
    // sync view angles from the camera: pointer-lock mouse look writes to it
    // directly between frames, so the look pad continues from where the mouse left off
    _eul.setFromQuaternion(camera.quaternion, 'YXZ');
    yaw = _eul.y; pitch = _eul.x;
    // combine keyboard + joystick; magnitude capped at 1 → analog speed
    let f = (keys.w ? 1 : 0) - (keys.s ? 1 : 0) + joyInput.f;
    let s = (keys.d ? 1 : 0) - (keys.a ? 1 : 0) + joyInput.s;
    const len = Math.hypot(f, s);
    if (len > 0.05) {
      if (inPond) swimMove = Math.min(len, 1);
      const dist = (keys.shift ? 2 : 4) * dt * Math.min(len, 1) * pondSpeed; // m/s — run by default, Shift = walk; slower in water
      fpControls.moveForward((f / len) * dist);
      fpControls.moveRight((s / len) * dist);
    }
    // eye level — C ducks (smooth), Space jumps with simple gravity
    let targetH = (keys.duck ? DUCK_H : EYE_H) + groundH(camera.position.x, camera.position.z);   // up and down the hills
    // POND (per user): wade in standing on the sloping bed; where it's too deep to stand, swim with the head just above
    // the surface (gentle bob); hold C to dive under, release to come back up. Slower in the water, no jumping.
    const water = grounded ? pond.depthAt(camera.position.x, camera.position.z) : null;
    inPond = !!water;
    pondSpeed = 1;
    if (water) {
      const standH = water.bedY + (keys.duck ? DUCK_H : EYE_H);
      const floatH = water.waterY + 0.2 + 0.025 * Math.sin(performance.now() * 0.0018);
      if (keys.duck) targetH = Math.max(water.bedY + 0.35, Math.min(water.bedY + DUCK_H, water.waterY - 0.6)); // dive
      else targetH = Math.max(standH, floatH);
      pondSpeed = standH >= floatH && !keys.duck ? 0.55 : 0.4;   // wading / swimming
    }
    if (grounded) {
      camera.position.y += (targetH - camera.position.y) * Math.min(1, dt * (inPond ? 3 : 12)); // crouch/stand (slow in water)
      if (Math.abs(camera.position.y - targetH) < 0.005) camera.position.y = targetH; // settle exactly on the ground
    } else {
      jumpVy -= GRAVITY * dt;
      camera.position.y += jumpVy * dt;
      if (jumpVy < 0 && camera.position.y <= targetH) { camera.position.y = targetH; jumpVy = 0; grounded = true; } // land
    }
    const r = Math.hypot(camera.position.x, camera.position.z);
    const RW = WORLD_R - 6; if (r > RW) { camera.position.x *= RW / r; camera.position.z *= RW / r; } // stay in the scene
  } else {
    // orbit view (per user): WASD flies the view — camera and orbit target move together; W/S along the direction the
    // camera FACES (so looking down, W descends toward what you look at), A/D strafe level. Faster when zoomed out;
    // Shift = slow. The camera stays 0.4 m above the ground and the target on/above it, within the scene.
    const f = (keys.w ? 1 : 0) - (keys.s ? 1 : 0), s = (keys.d ? 1 : 0) - (keys.a ? 1 : 0), len = Math.hypot(f, s);
    if (len > 0) {
      camera.getWorldDirection(_fwd);
      _right.crossVectors(_fwd, camera.up).normalize();
      const dist = (keys.shift ? 0.35 : 1) * Math.max(2.5, 0.6 * camera.position.distanceTo(controls.target)) * dt / len;
      _move.copy(_fwd).multiplyScalar(f * dist).addScaledVector(_right, s * dist);
      _move.y = Math.max(_move.y, 0.4 - camera.position.y); // glide just above the ground, never through it
      if (Math.hypot(controls.target.x + _move.x, controls.target.z + _move.z) < WORLD_R - 10) {
        camera.position.add(_move); controls.target.add(_move);
        // the orbit centre can't sink below the ground (clamping the MOVE by it stopped all descent — bug): re-seat
        // it where the view ray meets the ground, so the view direction is unchanged
        if (controls.target.y < 0) {
          const t = _fwd.y < -0.05 ? -camera.position.y / _fwd.y : 1.5;   // re-seat the orbit point ahead of the camera, never ON it
          controls.target.copy(camera.position).addScaledVector(_fwd, Math.max(t, 1.5));
          controls.target.y = Math.max(controls.target.y, 0);
        }
      }
    }
    // keep the orbit camera ≥ 0.3 m above the ground by capping how far it may swing UNDER the target (camera y =
    // target y + r·cos φ). Pushing the camera back up after the update instead shortened r every frame, so dragging
    // against the ground made the view creep toward the target until it hit something (drift bug, per user).
    const rr = camera.position.distanceTo(controls.target);
    controls.maxPolarAngle = Math.min(Math.PI * 0.95, Math.acos(THREE.MathUtils.clamp((0.3 - controls.target.y) / rr, -1, 1)));
    controls.update(); // orbit mode only — while walking it would overwrite our view angle
  }
  // under the surface: murky blue-green fog closes in; back to the normal haze when the head is out
  const under = camera.position.y < POND.waterY && !!pond.depthAt(camera.position.x, camera.position.z);
  if (under !== wasUnder) {
    wasUnder = under;
    const fb = fogBase();
    if (under) scene.fog.color.set(isNight ? 0x08262c : 0x2f747b); else scene.fog.color.copy(fb.c);
    scene.fog.near = under ? 0.3 : fb.n; scene.fog.far = under ? 9 : fb.f;
    pond.setUnder(under);
  }
  // debug view-direction readout (compass + axes)
  if (dbgChk.checked) {
    _eul.setFromQuaternion(camera.quaternion, 'YXZ'); // reuse (was a new Euler every frame)
    const c = compassText();
    dbgInfo.textContent = `facing ${c.dir} (${c.axes}) · yaw ${(_eul.y * 57.2958).toFixed(0)}° · pos ${camera.position.x.toFixed(1)}, ${camera.position.z.toFixed(1)}`;
  }
  const t = performance.now() * 0.001;
  campfire.update(t, dt, isNight);            // flames, embers, sparks, smoke
  fireLight.intensity = lerp(1.2, 2.6, nightK) * (0.85 + Math.sin(t * 17) * 0.15) * (1 + 0.4 * campfire.boost);
  blendLook(dt);                              // dusk / dawn and rain fading in and out
  pond.update(t, dt);                         // koi swim, ripples drift
  treeWind.value = t;                         // foliage sway
  life?.setSwim(swimMove);                    // water swish only while moving in the pond
  life?.update(t, dt);                        // grass, wildlife, fireflies, rain, sound
  campers.update(t, dt);                      // simulated campers wander between activities
  // slow cloud drift
  for (const c of clouds) { c.position.x += 0.004; if (c.position.x > 160) c.position.x = -160; }
  skyGroup.position.copy(camera.position); // keep the sky centred on the viewer (never clipped by camera.far)
  if (walking || fishing?.active) {                      // first person: a point ~8 m ahead on the ground
    camera.getWorldDirection(_sd); _sd.y = 0; _sd.normalize();
    updateShadowFrustum(_sc.copy(camera.position).addScaledVector(_sd, 8).setY(0), 16);
  } else updateShadowFrustum(controls.target, camera.position.distanceTo(controls.target));
  renderer.render(scene, camera);
  labelRenderer.render(scene, camera);
  if (firstFrame) { // scene is on screen: finish the bar and offer "Enter" (the click also unlocks the sound)
    firstFrame = false;
    ldFill.style.width = '100%'; ldPct.textContent = '100%'; ldStage.textContent = 'Ready';
    const loader = document.getElementById('loader'), enter = document.getElementById('ldEnter');
    loader.classList.remove('error'); loader.classList.add('ready');   // it did load after all
    enter.hidden = false; enter.focus();
    const go = () => {
      clearInterval(window.__ldTips);
      loader.classList.add('done');
      removeEventListener('keydown', onKey);
      setTimeout(() => loader.remove(), 650);
    };
    const onKey = e => { if (e.code === 'Enter' || e.code === 'Space') { e.preventDefault(); go(); } };
    enter.addEventListener('click', go);
    addEventListener('keydown', onKey);
  }
});
